import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"stock/仓位管理/加仓法.md","filePath":"stock/仓位管理/加仓法.md"}'),s={name:"stock/仓位管理/加仓法.md"};function r(c,p,n,_,d,i){return o(),e("div",null,p[0]||(p[0]=[a("<p>有四种情况：</p><p>1， 这是真的上涨趋势，你买了很多的仓位，赚大钱了；</p><p>2， 这是真的上涨趋势，你买了很少的仓位，赚了一点；</p><p>3， 这是假的上涨趋势，你买了很多的仓位，赔大钱了；</p><p>4， 这是假的上涨趋势，你买了很少的仓位，赔了一点；</p><p>未来是不可预知的，所以，前提条件是，先不要赔大钱。</p><p>这样，就解决了以上第三点的情况。</p><p>也就是说：无论是真的，还是假的上涨趋势，都不要一次性买很多仓位，去赌博真的上涨趋势，这样就能避免假的上涨趋势带来的巨大亏损。</p><p>好了，由于不重仓和全仓操作，避免了假的上涨趋势的巨大损失，下来考虑如何轻仓进场操作赚钱，尽可能多赚钱的问题了</p><p>从轻仓开始进场操作，</p><p>遇到真的上涨趋势怎么办？</p><p>遇到假的上涨趋势怎么办？</p><p>遇到真的上涨趋势，就要不断在这个轻仓的建仓仓位基础上加仓，前一个仓位不获利，下一个仓位不进场，由于上涨趋势有惯性，不可能一下子就开始，也不可能一下子就结束，在真的上涨趋势中平均200%的涨幅够你慢慢不断加仓赚钱的。</p><p>每一个仓位都是在前一个仓位获利的基础上进场加仓的，这就是上涨趋势仓位管理和资金分配的具体操作方法。</p><p>遇到假的上涨趋势，由于轻仓操作，所以损失不大，</p><p>另外，由于前一个仓位不获利，下一个仓位不进场，</p><p>所以，假的上涨趋势造成的损失非常有限，只有一个仓位，</p><p>这就是田忌赛马的具体运用，也是大数原则的概率思想---赚的时候，大；赔的时候，小。</p>",18)]))}const f=t(s,[["render",r]]);export{m as __pageData,f as default};
